package control

import "net/http"

func (s *Server) handleAccountPage(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/account/" {
		http.NotFound(w, r)
		return
	}
	if !accountMethod(w, r, "GET") {
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Content-Security-Policy", "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'")
	w.Write([]byte(accountPage))
}

// Browser callbacks keep a useful recovery path without echoing provider
// errors, principal identifiers, codes, state or membership diagnostics.
func accountLoginFailure(w http.ResponseWriter, status int) {
	accountPrivate(w)
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Content-Security-Policy", "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'")
	w.WriteHeader(status)
	w.Write([]byte(`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mnet - sign-in not completed</title><style>:root{font:100% system-ui,sans-serif;color:#1d1d1f;background:#f5f5f7;color-scheme:light}*{box-sizing:border-box}body{max-width:720px;margin:56px auto;padding:0 24px;line-height:1.65}main{background:white;border:1px solid rgb(0 0 0 / 0.09);border-radius:16px;padding:28px}h1{font-size:1.875rem;line-height:1.2;letter-spacing:-.03em}h1,p,footer{overflow-wrap:anywhere}a{color:#0066cc;text-underline-offset:4px}:focus-visible{outline:3px solid #0066cc;outline-offset:4px}footer{font-size:.875rem;margin-top:30px;color:#5a5a5f}@media(max-width:600px){body{margin:24px auto;padding:0 18px}main{padding:22px 18px}h1{font-size:1.25rem}}@media(forced-colors:active){button,.button{border:1px solid ButtonText}button:disabled{border-color:GrayText;color:GrayText}:focus-visible{outline-color:Highlight}}</style><main><svg aria-hidden="true" width="40" height="40" style="flex-shrink:0;vertical-align:middle;margin-right:12px" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><g transform="translate(0 0.75)"><polyline points="20,79 20,39 50,67 80,39 80,79" fill="none" stroke="#1D1D1F" stroke-width="21" stroke-linecap="round" stroke-linejoin="round"/><circle cx="50" cy="20" r="11" fill="#FF6A1A"/></g></svg><h1>Sign-in was not completed</h1><p>This login may have expired, been refused or opened in a different browser. Your identity must already have access to the selected network.</p><p><a href="/account/">Return to account sign-in</a> and start again in this browser. If access is still refused, ask your network operator to check membership and login setup.</p><p>Retrying does not enroll a device or grant membership. An existing session may still be active; use Sign out from the account page if needed.</p></main><footer>Mnet is provided by Fintex Australia Pty Ltd (ABN 60 688 406 108), New South Wales, Australia. Contact: <a href="mailto:contact@fintex.au">contact@fintex.au</a>.</footer></html>`))
}

const accountPage = `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mnet - your devices</title><style>
:root{font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","Segoe UI",Roboto,Inter,system-ui,sans-serif;color:#1d1d1f;background:#f5f5f7;color-scheme:light;font-size:100%}*{box-sizing:border-box}h1,h2,p,label{overflow-wrap:anywhere}input,select{min-width:0}body{max-width:1040px;margin:0 auto;padding:36px 28px}header{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:24px;margin-bottom:32px}h1{font-size:2.125rem;letter-spacing:-.035em;margin:0 0 8px;line-height:1.2}h2{font-size:1.562rem;letter-spacing:-.025em;line-height:1.25;margin:0 0 16px}p{line-height:1.65;margin:12px 0}a{color:#0066cc;text-underline-offset:4px}header>a{max-width:100%;padding:12px 16px;border:1px solid rgb(0 0 0 / 0.09);border-radius:10px;text-decoration:none;font-weight:600;white-space:nowrap}main{margin:0}#message{background:rgb(0 102 204 / 0.10);border:1px solid rgb(0 0 0 / 0.09);border-radius:16px;padding:16px 20px;line-height:1.55;margin-bottom:20px;overflow-wrap:anywhere}section{background:white;border:1px solid rgb(0 0 0 / 0.09);border-radius:16px;padding:28px}#login{max-width:620px}label{display:block;font-size:0.875rem;font-weight:650;margin:20px 0 8px}input{width:100%;border:1px solid rgb(0 0 0 / 0.16);border-radius:10px;padding:14px;font:inherit;color:#1d1d1f;background:#fff;min-height:50px}button{background:#0066cc;color:white;border:0;border-radius:10px;padding:14px 20px;font:inherit;font-weight:600;cursor:pointer;margin:16px 6px 0 0;min-height:50px}button:hover{background:#0058b0}button:disabled{background:#e8e8ed;color:#5a5a5f;cursor:wait}.secondary{background:#e8e8ed;color:#1d1d1f}.secondary:hover{background:rgb(0 0 0 / 0.09)}:focus-visible{outline:3px solid #0066cc;outline-offset:4px}.hint,footer{font-size:0.875rem;color:#5a5a5f;line-height:1.6}.eyebrow{text-transform:uppercase;font-size:0.75rem;letter-spacing:.09em;font-weight:700;color:#0066cc;margin:0 0 10px}.scope{border-left:3px solid #0066cc;padding:4px 0 4px 16px;margin:20px 0}.network-context{background:#f5f5f7;border-radius:10px;padding:12px 16px;overflow-wrap:anywhere}.device-table{width:100%;border-collapse:collapse;text-align:left;margin:24px 0 12px}th,td{padding:18px 12px;border-bottom:1px solid rgb(0 0 0 / 0.09);overflow-wrap:anywhere}th{font-size:0.8125rem;color:#5a5a5f;font-weight:650}td:first-child{font-weight:600}.address{font-family:ui-monospace,monospace;font-size:0.875rem}#empty{padding:24px;background:#f5f5f7;border:1px dashed rgb(0 0 0 / 0.16);border-radius:10px}footer{margin:32px 0;max-width:760px}[hidden]{display:none!important}@media(max-width:600px){body{padding:24px 18px}header{align-items:flex-start;gap:12px}h1{font-size:1.75rem}header>a{padding:10px}section{padding:22px 18px}h2{font-size:1.438rem}th,td{padding:16px 8px}button{width:100%;margin-right:0}.address{font-size:0.8125rem}#message{padding:14px 16px}}@media(min-width:900px){#loginForm{max-width:460px}}@media(prefers-reduced-motion:no-preference){button,a{transition:background-color .15s ease}}
.device-field-label{display:none}
@media(max-width:600px){
.device-table,.device-table tbody{display:block;width:100%}
.device-table thead{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
.device-table tbody tr{display:block;padding:16px;margin-bottom:16px;background:#f5f5f7;border:1px solid rgb(0 0 0 / .09);border-radius:10px}
.device-table td{display:block;padding:0;border:0;overflow-wrap:anywhere}.device-table td+td{margin-top:16px}
.device-field-label{display:block;font-family:system-ui,sans-serif;font-size:.75rem;font-weight:600;color:#5a5a5f;margin-bottom:6px}
}
@media(forced-colors:active){button,.button{border:1px solid ButtonText}button:disabled{border-color:GrayText;color:GrayText}:focus-visible{outline-color:Highlight}}</style><header><div><svg aria-hidden="true" width="40" height="40" style="flex-shrink:0;vertical-align:middle;margin-right:12px" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><g transform="translate(0 0.75)"><polyline points="20,79 20,39 50,67 80,39 80,79" fill="none" stroke="#1D1D1F" stroke-width="21" stroke-linecap="round" stroke-linejoin="round"/><circle cx="50" cy="20" r="11" fill="#FF6A1A"/></g></svg><p class="eyebrow">Mnet / Member account</p><h1>Your Mnet devices</h1><span class="hint">Approved devices, scoped to your identity</span></div><a href="/">Back to Mnet</a></header>
<main><div id="message" role="status" aria-live="polite">Checking your session...</div>
<section id="sessionRecovery" hidden><h2 id="sessionRecoveryHeading" tabindex="-1">Device list unavailable</h2><p>We could not check this browser session. This does not confirm that you are signed out. Retry the device list, or sign out of this browser.</p><button id="retryDevices" type="button">Retry device list</button> <button id="recoveryLogout" class="secondary" type="button">Sign out</button></section>
<section id="logoutRecovery" hidden><h2>Sign-out not confirmed</h2><p>Your browser session may still be active. Retry sign-out before leaving this browser, or check the session without starting a new sign-in.</p><button id="retrySignout" type="button">Retry sign-out</button> <button id="inspectSession" class="secondary" type="button">Check this session</button><p class="hint">Checking only reads this browser session. It does not sign you in again.</p></section>
<section id="login" hidden><p class="eyebrow">Member access</p><h2>Sign in to your network</h2><p>Use the network ID provided by your operator. Your identity must already be a member of that network.</p>
<form id="loginForm"><label for="network">Network ID</label><input id="network" aria-describedby="loginFeedback" name="network_id" autocomplete="off" maxlength="256" required><p id="loginFeedback" class="hint" role="status" aria-live="polite"></p><button id="signIn" type="submit">Continue to sign in</button></form>
<p class="hint scope">Signing in does not enroll a device or grant membership. Ask your operator if access has not been set up.</p></section>
<section id="devices" hidden><p class="eyebrow">Your account</p><h2 id="devicesHeading" tabindex="-1">Your approved devices</h2><p class="hint network-context">Network ID: <span id="currentNetwork" style="overflow-wrap:anywhere"></span></p><p>Only devices approved with your verified identity in this network appear here. This list is not a live online-status check.</p>
<table class="device-table" role="table" aria-label="Approved devices"><thead role="rowgroup"><tr role="row"><th scope="col">Device</th><th scope="col">Mesh address</th></tr></thead><tbody id="deviceRows" role="rowgroup"></tbody></table><p id="empty" hidden>No approved, unexpired devices were found for your identity.</p>
<button class="secondary" id="refresh" type="button">Refresh</button> <button class="secondary" id="logout" type="button">Sign out</button>
<p class="hint">Signing out ends this browser session. It does not disconnect VPN devices.</p></section></main>
<footer>Mnet is provided by Fintex Australia Pty Ltd (ABN 60 688 406 108), New South Wales, Australia. Contact: <a href="mailto:contact@fintex.au">contact@fintex.au</a>.</footer>
<script>
const el=id=>document.getElementById(id);let generation=0,signingOut=false,signingIn=false;
function clearPrivate(){el('sessionRecovery').hidden=true;el('logoutRecovery').hidden=true;el('currentNetwork').textContent='';el('deviceRows').replaceChildren();el('empty').hidden=true;el('devices').hidden=true;el('network').value='';}
function loginStatus(message){el('message').textContent=message;el('loginFeedback').textContent=message;}
function signedOut(message){el('loginFeedback').textContent='';clearPrivate();el('login').hidden=false;el('message').textContent=message;el('network').focus();}
async function load(){if(signingOut)return;const current=++generation;try{const r=await fetch('/account/api/devices',{cache:'no-store'});if(current!==generation||signingOut)return;if(r.status===401||r.status===403){signedOut('Sign in with an existing network membership.');return;}if(!r.ok)throw Error();const data=await r.json();if(current!==generation||signingOut)return;if(!data||typeof data.network_id!=='string'||!data.network_id||!Array.isArray(data.devices)||!data.devices.every(device=>device&&typeof device.ID==='string'&&device.ID.length>0&&typeof device.Name==='string'&&typeof device.IPv4==='string'))throw Error();const rows=data.devices.map(device=>{const row=document.createElement('tr');row.setAttribute('role','row');for(const [index,value] of [device.Name,device.IPv4].entries()){const cell=document.createElement('td');cell.setAttribute('role','cell');const label=document.createElement('span');label.className='device-field-label';label.setAttribute('aria-hidden','true');label.textContent=index===0?'Device':'Mesh address';cell.append(label,document.createTextNode(value));if(index===1)cell.className='address';row.append(cell);}return row;});el('deviceRows').replaceChildren(...rows);el('currentNetwork').textContent=data.network_id;el('empty').hidden=data.devices.length!==0;const entering=el('devices').hidden;el('sessionRecovery').hidden=true;el('logoutRecovery').hidden=true;el('login').hidden=true;el('devices').hidden=false;if(entering)el('devicesHeading').focus();el('message').textContent='Signed in. Device approval is separate from current connectivity.';}catch{if(current===generation&&!signingOut){clearPrivate();el('login').hidden=true;el('sessionRecovery').hidden=false;el('message').textContent='Could not read your devices. Try again.';el('sessionRecoveryHeading').focus();}}}
el('loginForm').addEventListener('submit',async e=>{e.preventDefault();if(signingIn)return;if(!el('network').value.trim()){loginStatus('Enter the network ID provided by your operator.');el('network').setAttribute('aria-invalid','true');el('network').focus();return;}signingIn=true;el('network').removeAttribute('aria-invalid');el('signIn').disabled=true;loginStatus('Opening your identity provider...');try{const r=await fetch('/account/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({network_id:el('network').value.trim()})});if(!r.ok)throw Error();const data=await r.json();const target=new URL(data.authorization_url);if(!['https:','http:'].includes(target.protocol))throw Error();location.assign(target.href);}catch{loginStatus('Could not start sign-in. Check the network ID and ask your operator to confirm login setup.');el('signIn').disabled=false;signingIn=false;el('network').focus();}});
el('network').addEventListener('input',()=>el('network').removeAttribute('aria-invalid'));
el('refresh').addEventListener('click',load);el('retryDevices').addEventListener('click',load);el('recoveryLogout').addEventListener('click',()=>el('logout').click());
el('logout').addEventListener('click',async()=>{if(signingOut)return;signingOut=true;++generation;clearPrivate();el('login').hidden=true;el('message').textContent='Signing out...';try{const r=await fetch('/account/api/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error();signedOut('Signed out.');}catch{el('login').hidden=true;el('message').textContent='Could not confirm sign-out. Retry before leaving this browser.';el('logoutRecovery').hidden=false;el('retrySignout').focus();}finally{signingOut=false;}});
el('retrySignout').addEventListener('click',()=>el('logout').click());el('inspectSession').addEventListener('click',load);
load();
</script></html>`
